1	import {ToolRegistry} from './registry.js';
2	import {createChatOrchestrator} from '../chatOrchestrator.js';
3	import {PromptBuilder} from '../../infrastructure/builders/promptBuilder.js';
4	import {setLogger} from '../../shared/logger.js';
5	import type {Logger} from '../../shared/logger.js';
6	import type {AIProvider, MessageChunk, SendMessageParams, ToolResultMessage} from '../../types/ai.js';
7	import type {ChatSession} from '../../types/session.js';
8	
9	const SENT_AT = '2026-01-01T00:00:00.000Z';
10	
11	describe('ToolRegistry inputSchema validation acceptance', () => {
12	  afterEach(() => {
13	    setLogger(undefined);
14	  });
15	
16	  it('rejects input missing a required property with a ToolResponse and never calls the executor', async () => {
17	    const registry = new ToolRegistry();
18	    let executorCalls = 0;
19	    registry.register(
20	      {
21	        name: 'get_weather',
22	        description: 'Get weather for a location',
23	        inputSchema: {
24	          type: 'object',
25	          properties: {location: {type: 'string'}},
26	          required: ['location'],
27	        },
28	      },
29	      async () => {
30	        executorCalls += 1;
31	        return 'sunny';
32	      }
33	    );
34	
35	    const response = await registry.execute('get_weather', {});
36	
37	    expect({
38	      executorCalls,
39	      mentionsRequiredField: response.result.includes('location') && /required/i.test(response.result),
40	    }).toEqual({
41	      executorCalls: 0,
42	      mentionsRequiredField: true,
43	    });
44	  });
45	
46	  it('rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs', async () => {
47	    const recordedLogs: string[] = [];
48	    const recordLine = (category: string, message: string, fields?: Record<string, unknown>) => {
49	      recordedLogs.push(JSON.stringify({category, message, fields}));
50	    };
51	    const logger: Logger = {
52	      debug: recordLine,
53	      info: recordLine,
54	      warn: recordLine,
55	      error: recordLine,
56	    };
57	    setLogger(logger);
58	
59	    const registry = new ToolRegistry();
60	    let executorCalls = 0;
61	    registry.register(
62	      {
63	        name: 'ssn_lookup',
64	        description: 'Look up record by identifier',
65	        inputSchema: {
66	          type: 'object',
67	          properties: {ssn: {type: 'string'}},
68	          required: ['ssn'],
69	        },
70	      },
71	      async () => {
72	        executorCalls += 1;
73	        return 'found';
74	      }
75	    );
76	
77	    const response = await registry.execute('ssn_lookup', {ssn: 123456789});
78	
79	    expect({
80	      executorCalls,
81	      mentionsField: response.result.includes('ssn'),
82	      mentionsExpectedType: response.result.includes('string'),
83	      leaksValueInResult: response.result.includes('123456789'),
84	      leaksValueInLogs: recordedLogs.some(line => line.includes('123456789')),
85	    }).toEqual({
86	      executorCalls: 0,
87	      mentionsField: true,
88	      mentionsExpectedType: true,
89	      leaksValueInResult: false,
90	      leaksValueInLogs: false,
91	    });
92	  });
93	
94	  it('throws at register time naming the tool when a static inputSchema cannot be compiled', () => {
95	    const registry = new ToolRegistry();
96	
97	    expect(() =>
98	      registry.register(
99	        {
100	          name: 'broken_weather',
101	          description: 'Has an invalid JSON Schema type',
102	          inputSchema: {
103	            type: 'object',
104	            properties: {location: {type: 'not-a-json-schema-type'}},
105	          },
106	        },
107	        async () => 'unreachable'
108	      )
109	    ).toThrow(/broken_weather/);
110	  });
111	
112	  it('returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round', async () => {
113	    const registry = new ToolRegistry();
114	    const executorInputs: Array<Record<string, unknown>> = [];
115	    registry.register(
116	      () => ({
117	        name: 'get_weather',
118	        description: 'Get weather for a location',
119	        inputSchema: {
120	          type: 'object',
121	          properties: {location: {type: 'string'}},
122	          required: ['location'],
123	        },
124	      }),
125	      async input => {
126	        executorInputs.push(input);
127	        return `22C in ${String(input.location)}`;
128	      }
129	    );
130	
131	    let firstRoundToolResult = '';
132	    let round = 0;
133	    const provider: AIProvider = {
134	      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
135	        round += 1;
136	        if (round === 1) {
137	          yield {type: 'tool_use', toolCall: {id: 'call-1', name: 'get_weather', input: {}}};
138	          yield {type: 'stop', stopReason: 'tool_use'};
139	          return;
140	        }
141	        if (round === 2) {
142	          const lastMessage = params.messages[params.messages.length - 1] as ToolResultMessage;
143	          firstRoundToolResult = lastMessage.content[0]?.content ?? '';
144	          yield {
145	            type: 'tool_use',
146	            toolCall: {id: 'call-2', name: 'get_weather', input: {location: 'Paris'}},
147	          };
148	          yield {type: 'stop', stopReason: 'tool_use'};
149	          return;
150	        }
151	        yield {type: 'text', text: '22C in Paris'};
152	        yield {type: 'stop', stopReason: 'end_turn'};
153	      },
154	      async generateStructured<T>(): Promise<T> {
155	        return {} as T;
156	      },
157	    };
158	
159	    const orchestrator = createChatOrchestrator(
160	      provider,
161	      new PromptBuilder({identity: 'You are a test assistant.'}),
162	      registry
163	    );
164	    const session: ChatSession = {
165	      sessionId: 's-retry',
166	      userId: 'u1',
167	      entries: [{role: 'user', content: 'Weather in Paris?', timestamp: SENT_AT}],
168	    };
169	
170	    const reply = await orchestrator.processMessage(session);
171	
172	    expect({
173	      reply,
174	      executorInputs,
175	      firstAttemptRejectedForLocation:
176	        firstRoundToolResult.includes('location') && /required/i.test(firstRoundToolResult),
177	    }).toEqual({
178	      reply: '22C in Paris',
179	      executorInputs: [{location: 'Paris'}],
180	      firstAttemptRejectedForLocation: true,
181	    });
182	  });
183	});
